import{_ as t,o,c as d,ag as a}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/sheets/formulas-autocomplete.png",c="/docs/images/sheets/formulas-functions-browser.png",p=JSON.parse('{"title":"Write formulas","description":"Type = in a cell to calculate a value from numbers, other cells, and functions.","frontmatter":{"title":"Write formulas","description":"Type = in a cell to calculate a value from numbers, other cells, and functions.","type":"how-to"},"headers":[],"relativePath":"sheets/formulas.md","filePath":"sheets/formulas.md"}'),n={name:"sheets/formulas.md"};function l(s,e,i,h,u,m){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="write-formulas" tabindex="-1">Write formulas <a class="header-anchor" href="#write-formulas" aria-label="Permalink to &quot;Write formulas&quot;">​</a></h1><p>Type <code>=</code> in a cell to calculate a value from numbers, other cells, and functions. A formula recalculates whenever a cell it uses changes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access to enter formulas.</li><li>For every function and its syntax, see the <a href="/docs/sheets/functions.html">Function reference</a>.</li></ul></div><h2 id="enter-a-formula" tabindex="-1">Enter a formula <a class="header-anchor" href="#enter-a-formula" aria-label="Permalink to &quot;Enter a formula&quot;">​</a></h2><ol><li>Click the cell where the result should appear.</li><li>Type <code>=</code> followed by the formula, for example <code>=SUM(B2:B7)</code>.</li><li>As you type a function name, a list of matching functions appears. Press <code>↓</code> or <code>↑</code> to choose one, then <code>Tab</code> or <code>Enter</code> to insert it with its opening parenthesis.</li><li>While you type the arguments, a hint shows the function&#39;s syntax. To add a reference, click a cell or drag across a range instead of typing it.</li><li>Press <code>Enter</code>.</li></ol><p>The cell shows the result. Select the cell to see the formula in the formula bar.</p><p><img src="'+r+'" alt="Function list under a cell after typing =SU, with SUM highlighted"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Double-tap the cell and type the formula in the edit panel, then tap the check mark (<strong>Confirm editing</strong>). The function list and syntax hint don&#39;t appear in the edit panel.</p><h2 id="reference-cells-ranges-and-other-tabs" tabindex="-1">Reference cells, ranges, and other tabs <a class="header-anchor" href="#reference-cells-ranges-and-other-tabs" aria-label="Permalink to &quot;Reference cells, ranges, and other tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To refer to</th><th>Write</th><th>Example</th></tr></thead><tbody><tr><td>One cell</td><td>Column letter and row number</td><td><code>=A1*2</code></td></tr><tr><td>A range</td><td>Two corners joined by <code>:</code></td><td><code>=SUM(A1:C10)</code></td></tr><tr><td>Whole columns</td><td>Column letters only</td><td><code>=SUM(B:B)</code></td></tr><tr><td>Whole rows</td><td>Row numbers only</td><td><code>=SUM(2:2)</code></td></tr><tr><td>A cell on another tab</td><td>Tab name, <code>!</code>, reference</td><td><code>=Sheet2!A1</code></td></tr><tr><td>A tab whose name has spaces or symbols</td><td>The name in single quotes</td><td><code>=&#39;Q1 Sales&#39;!B2:B10</code></td></tr></tbody></table><p>Tab names in a reference ignore case, so <code>sheet2!A1</code> and <code>Sheet2!A1</code> are the same cell.</p><p>While you edit a formula, clicking a column letter inserts the whole column, such as <code>B:B</code>, and clicking a row number inserts the whole row.</p><h2 id="keep-a-reference-fixed" tabindex="-1">Keep a reference fixed <a class="header-anchor" href="#keep-a-reference-fixed" aria-label="Permalink to &quot;Keep a reference fixed&quot;">​</a></h2><p>A plain reference such as <code>B2</code> changes when you fill or copy the formula to another cell. Add <code>$</code> to fix part of it:</p><table tabindex="0"><thead><tr><th>Reference</th><th>When filled to another cell</th></tr></thead><tbody><tr><td><code>B2</code></td><td>Column and row both change</td></tr><tr><td><code>$B$2</code></td><td>Neither changes</td></tr><tr><td><code>B$2</code></td><td>Only the column changes</td></tr><tr><td><code>$B2</code></td><td>Only the row changes</td></tr></tbody></table><p>To switch modes, put the cursor on a reference while editing and press <code>F4</code>. Each press cycles <code>B2</code> → <code>$B$2</code> → <code>B$2</code> → <code>$B2</code> → <code>B2</code>.</p><h2 id="find-a-function" tabindex="-1">Find a function <a class="header-anchor" href="#find-a-function" aria-label="Permalink to &quot;Find a function&quot;">​</a></h2><ol><li>Click <strong>Functions</strong> in the toolbar. On a phone, tap ⋮ (<strong>More formatting options</strong>) and select <strong>Functions</strong>.</li><li>Type in <strong>Search by name or description</strong>, for example <code>lookup</code>.</li><li>Click a function to insert it into the selected cell.</li></ol><p>The panel lists functions by category and shows each one&#39;s syntax and description.</p><p><img src="'+c+'" alt="Functions panel filtered by &quot;lookup&quot;, showing XLOOKUP and VLOOKUP with their syntax"></p><h2 id="return-several-values-at-once" tabindex="-1">Return several values at once <a class="header-anchor" href="#return-several-values-at-once" aria-label="Permalink to &quot;Return several values at once&quot;">​</a></h2><p>Some formulas return a whole range. Enter the formula in one cell, and the results fill the cells below and to the right of it.</p><table tabindex="0"><thead><tr><th>Formula</th><th>Result</th></tr></thead><tbody><tr><td><code>={1,2;3,4}</code></td><td>A 2-by-2 block of numbers</td></tr><tr><td><code>=SORT(A2:C20, 2, -1)</code></td><td>The range sorted by its second column, largest first (<code>1</code> sorts smallest first)</td></tr><tr><td><code>=TRANSPOSE(A1:C2)</code></td><td>The range with rows and columns swapped</td></tr><tr><td><code>=HSTACK(A2:A20, C2:C20)</code></td><td>Two ranges side by side</td></tr><tr><td><code>=CHOOSECOLS(A2:D20, 1, 3)</code></td><td>Only the first and third columns of the range</td></tr></tbody></table><p>Only the first cell holds the formula. To change or remove the results, edit or delete that cell. If a cell in the way already has data, the formula shows <code>#REF!</code> until you clear it.</p><h2 id="use-operators" tabindex="-1">Use operators <a class="header-anchor" href="#use-operators" aria-label="Permalink to &quot;Use operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>+</code> <code>-</code> <code>*</code> <code>/</code></td><td>Add, subtract, multiply, divide</td><td><code>=B2*1.1</code></td></tr><tr><td><code>^</code></td><td>Power</td><td><code>=2^10</code></td></tr><tr><td><code>%</code></td><td>Percent</td><td><code>=B2*15%</code></td></tr><tr><td><code>&amp;</code></td><td>Join text</td><td><code>=A2&amp;&quot; &quot;&amp;B2</code></td></tr><tr><td><code>=</code> <code>&lt;&gt;</code> <code>&lt;</code> <code>&gt;</code> <code>&lt;=</code> <code>&gt;=</code></td><td>Compare; returns <code>TRUE</code> or <code>FALSE</code></td><td><code>=B2&gt;=100</code></td></tr><tr><td><code>{ }</code></td><td>Array: <code>,</code> between columns, <code>;</code> between rows</td><td><code>={1,2;3,4}</code></td></tr></tbody></table><p>Put text in double quotes: <code>&quot;Over&quot;</code>. To include a quote inside text, double it: <code>&quot;Say &quot;&quot;hi&quot;&quot;&quot;</code>.</p><h2 id="common-formulas" tabindex="-1">Common formulas <a class="header-anchor" href="#common-formulas" aria-label="Permalink to &quot;Common formulas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Formula</th></tr></thead><tbody><tr><td>Total a column</td><td><code>=SUM(C2:C7)</code></td></tr><tr><td>Average</td><td><code>=AVERAGE(C2:C7)</code></td></tr><tr><td>Largest or smallest value</td><td><code>=MAX(C2:C7)</code>, <code>=MIN(C2:C7)</code></td></tr><tr><td>Count cells that match</td><td><code>=COUNTIF(D2:D7, &quot;&lt;0&quot;)</code></td></tr><tr><td>Total cells that match</td><td><code>=SUMIF(A2:A20, &quot;Rent&quot;, C2:C20)</code></td></tr><tr><td>Choose between two values</td><td><code>=IF(D2&lt;0, &quot;Over&quot;, &quot;OK&quot;)</code></td></tr><tr><td>Replace an error with a value</td><td><code>=IFERROR(C2/B2, 0)</code></td></tr><tr><td>Look up a value</td><td><code>=XLOOKUP(&quot;Bob&quot;, A2:A20, C2:C20)</code></td></tr><tr><td>Look up a value in the third column of a table</td><td><code>=VLOOKUP(&quot;Bob&quot;, A2:C20, 3, FALSE)</code></td></tr><tr><td>Look up by position</td><td><code>=INDEX(C2:C20, MATCH(&quot;Bob&quot;, A2:A20, 0))</code></td></tr><tr><td>Choose among several conditions</td><td><code>=IFS(C2&gt;=30, &quot;High&quot;, C2&gt;=20, &quot;Medium&quot;, TRUE, &quot;Low&quot;)</code></td></tr><tr><td>Join text with a separator</td><td><code>=TEXTJOIN(&quot;, &quot;, TRUE, A2:A5)</code></td></tr><tr><td>Days between two dates</td><td><code>=DAYS(B2, A2)</code></td></tr></tbody></table><h2 id="fix-an-error-value" tabindex="-1">Fix an error value <a class="header-anchor" href="#fix-an-error-value" aria-label="Permalink to &quot;Fix an error value&quot;">​</a></h2><p>When a formula can&#39;t produce a result, the cell shows an error value instead.</p><table tabindex="0"><thead><tr><th>Value</th><th>What it means</th><th>Try this</th></tr></thead><tbody><tr><td><code>#DIV/0!</code></td><td>The formula divides by zero or an empty cell.</td><td>Check the divisor, or wrap the formula in <code>IFERROR</code>.</td></tr><tr><td><code>#VALUE!</code></td><td>An argument has a value the function doesn&#39;t accept, such as a <code>SORT</code> order other than <code>1</code> or <code>-1</code>.</td><td>Check the arguments against the function&#39;s syntax.</td></tr><tr><td><code>#REF!</code></td><td>A reference is invalid, the formula refers to its own cell (a circular reference), or a multi-cell result is blocked by data.</td><td>Fix the reference, keep the formula&#39;s own cell out of its ranges, or clear the cells where the results go.</td></tr><tr><td><code>#NAME?</code></td><td>The function name isn&#39;t recognized.</td><td>Check the spelling against the <a href="/docs/sheets/functions.html">Function reference</a>.</td></tr><tr><td><code>#N/A</code></td><td>A lookup found no match.</td><td>Check the search value, or add an <code>if_not_found</code> argument to <code>XLOOKUP</code>.</td></tr><tr><td><code>#NUM!</code></td><td>A number is out of range for the function.</td><td>Check the arguments&#39; limits.</td></tr><tr><td><code>#ERROR!</code></td><td>The formula can&#39;t be read, for example because of a missing parenthesis.</td><td>Check the formula&#39;s syntax.</td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Formulas can read sheet tabs only, not data source or lakehouse tabs. To calculate with query results, copy them into a sheet tab.</li><li>Named ranges aren&#39;t supported. Use cell references.</li><li>Text used in arithmetic counts as <code>0</code>. For example, <code>=A1*2</code> returns <code>0</code> when <strong>A1</strong> holds <code>abc</code>.</li><li><code>FILTER</code> needs a range of <code>TRUE</code> and <code>FALSE</code> cells as its condition. A comparison such as <code>A2:A20&gt;100</code> returns <code>#VALUE!</code>.</li><li><code>FILTER</code>, <code>UNIQUE</code>, <code>SEQUENCE</code>, <code>SORTBY</code>, <code>VSTACK</code>, <code>TAKE</code>, <code>DROP</code>, <code>TOCOL</code>, <code>FLATTEN</code>, and <code>SPLIT</code> return only their first value, not a whole range.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/functions.html">Function reference</a> for every function and its syntax.</li><li><a href="/docs/sheets/build-a-budget.html">Build a budget</a> to practice <code>SUM</code>, <code>IF</code>, and fill down.</li><li><a href="/docs/sheets/edit-and-format.html">Edit and format cells</a> to fill a formula down a column.</li><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a> for editing keys such as <code>F4</code>.</li></ul>',37)])])}const b=t(n,[["render",l]]);export{p as __pageData,b as default};
